  /* ---------- modals ---------- */
  const modal = $('#modal');
  const modalBody = $('#modal-body');

  window.__miseUpdateResult = function (payloadRaw) {
    const el = $('#update-status');
    const apply = $('#apply-update-btn');
    const button = document.querySelector('[data-action="check-updates"]');
    if (button) {
      button.disabled = false;
      button.innerHTML = `${icon('refresh')}Check for updates`;
    }
    let payload = null;
    try {
      payload = typeof payloadRaw === 'string' ? JSON.parse(payloadRaw) : payloadRaw;
    } catch (_) { payload = null; }
    if (!payload) {
      if (el) el.textContent = 'Update check returned something Mise could not read.';
      return;
    }
    const vn = esc(payload.versionName || '');
    const vc = esc(String(payload.webVersionCode == null ? '' : payload.webVersionCode));
    const versionLabel = vn && vc ? `Mise ${vn} (content v${vc})` : `Mise ${vn || 'unknown'}`;
    const latest = $('#build-latest');
    if (payload.status === 'updated') {
      if (latest) latest.textContent = `Mise ${vn} · content v${vc}`;
      if (el) el.textContent = `Recipe content updated to ${vn} (content v${vc}).`;
      if (apply) apply.hidden = true;
      return;
    }
    if (payload.status === 'apk') {
      if (latest) latest.textContent = `Mise ${vn}`;
      if (el) el.textContent = `${versionLabel} is available to install. Your recipes stay on this device.`;
      if (apply) apply.hidden = false;
      return;
    }
    if (payload.status === 'uptodate') {
      if (latest) latest.textContent = versionLabel;
      if (el) el.textContent = `${versionLabel} is the latest on this channel.`;
      if (apply) apply.hidden = true;
      return;
    }
    if (el) el.textContent = payload.message ? `Update check failed: ${payload.message}` : 'Update check failed.';
  };

